export function diff(a, b) {
  if (typeof a !== 'string') a = String(a ?? '');
  ...
  const ta = tokenize(a), tb = tokenize(b);
  const map = new Map();
  const enc = (t) => { let id = map.get(t); if (id === undefined) { id = map.size; map.set(t, id); } return id; };
  const N = ta.length, M = tb.length;
  const A = new Int32Array(N); for (let i = 0; i < N; i++) A[i] = enc(ta[i]);
  const B = new Int32Array(M); for (let i = 0; i < M; i++) B[i] = enc(tb[i]);

  const ops = []; // [t, i]: t: 0 eq(A idx), 1 del(A idx), 2 ins(B idx)

  let start = 0;
  while (start < N && start < M && A[start] === B[start]) start++;
  let endA = N, endB = M;
  while (endA > start && endB > start && A[endA - 1] === B[endB - 1]) { endA--; endB--; }

  for (let i = 0; i < start; i++) ops.push([0, i]);

  const n = endA - start, m = endB - start;
  if (n > 0 && m > 0) {
    myersOps(A, B, start, endA, start, endB, ops);
  } else {
    for (let i = start; i < endA; i++) ops.push([1, i]);
    for (let j = start; j < endB; j++) ops.push([2, j]);
  }

  for (let i = endA; i < N; i++) ops.push([0, i]);

  // merge
  const out = [];
  for (const [t, i] of ops) {
    const text = t === 2 ? tb[i] : ta[i];
    const op = t === 0 ? 'eq' : t === 1 ? 'del' : 'ins';
    const last = out[out.length - 1];
    if (last && last.op === op) last.text += text;
    else out.push({ op, text });
  }
  return out;
}
