// worddiff.mjs — zero-dependency, word-level diff for Node.js (ESM).
//
// exports:
//   diff(a, b)        -> [{ op: 'eq' | 'del' | 'ins', text }, ...]
//   toUnified(ops)    -> string with inline [-deleted-] and {+inserted+} markup
//
// Algorithm: Myers O((N+M)·D) edit script on word tokens (integer-encoded),
// with common prefix/suffix trimming. Memory is O(D^2) for the trace
// (only the touched cells are stored per d-step), which is tiny for real
// documents with few differences.

/**
 * Split a string into tokens that concatenate back to the original string.
 * Tokens are: word characters runs, whitespace runs, and any other
 * single character (punctuation etc.). Full coverage is guaranteed.
 */
function tokenize(s) {
  const re = /\w+|\s+|[\s\S]/g;
  const out = [];
  let m;
  while ((m = re.exec(s)) !== null) out.push[m[0]] = undefined, out.push(m[0]);
  return out;
}

// op codes used internally: 0 = eq (index into A), 1 = del (index into A),
// 2 = ins (index into B)
const EQ = 0, DEL = 1, INS = 2;

/**
 * Myers diff on slices A[a0..a1) vs B[b0..b1) of integer-encoded tokens.
 * Appends forward-order [code, tokenIndex] pairs to `ops`.
 */
function myersOps(A, B, a0, a1, b0, b1, ops) {
  const N = a1 - a0;
  const M = b1 - b0;
  const offset = N + M;
  const v = new Int32Array(2 * offset + 3); // furthest x per diagonal k+offset
  const trace = [];
  let D = -1;

  outer:
  for (let d = 0; d <= offset; d++) {
    const row = new Int32Array(d + 1); // row[ki] holds x for k = -d + 2*ki
    trace.push(row);
    for (let ki = 0; ki <= d; ki++) {
      const k = -d + 2 * ki;
      let x;
      if (k === -d || (k !== d && v[offset + k - 1] < v[offset + k + 1])) {
        x = v[offset + k + 1];          // insertion (move down)
      } else {
        x = v[offset + k - 1] + 1;      // deletion (move right)
      }
      let y = x - k;
      while (x < N && y < M && A[a0 + x] === B[b0 + y]) { x++; y++; } // snake
      row[ki] = x;
      v[offset + k] = x;
      if (x >= N && y >= M) { D = d; break outer; }
    }
  }

  // Backtrack from (N, M) to (0, 0), collecting ops in reverse order.
  const rev = [];
  let x = N, y = M;
  for (let d = D; d >= 1; d--) {
    const tp = trace[d - 1];
    const k = x - y;
    let pk;
    if (k === -d || (k !== d && tp[(k + d - 2) >> 1] < tp[(k + d) >> 1])) {
      pk = k + 1;
    } else {
      pk = k - 1;
    }
    const px = tp[(pk + d - 1) >> 1];
    const py = px - pk;
    while (x > px && y > py) { rev.push([EQ, a0 + x - 1]); x--; y--; }
    if (x === px) { rev.push([INS, b0 + y - 1]); y--; }
    else { rev.push([DEL, a0 + x - 1]); x--; }
  }
  while (x > 0 && y > 0) { rev.push([EQ, a0 + x - 1]); x--; y--; }
  for (let i = rev.length - 1; i >= 0; i--) ops.push(rev[i]);
}

/**
 * Word-level diff. Returns a minimal-ish edit script as an array of
 * runs: { op: 'eq' | 'del' | 'ins', text }. Adjacent tokens with the same
 * op are merged into a single run. Concatenating the text of all runs with
 * op !== 'ins' reproduces `a`; with op !== 'del' reproduces `b`.
 */
export function diff(a, b) {
  a = String(a);
  b = String(b);

  const ta = tokenize(a);
  const tb = tokenize(b);
  const N = ta.length;
  const M = tb.length;

  // Integer-encode tokens for cheap comparisons.
  const dict = new Map();
  const encode = (tokens) => {
    const ids = new Int32Array(tokens.length);
    for (let i = 0; i < tokens.length; i++) {
      const t = tokens[i];
      let id = dict.get(t);
      if (id === undefined) { id = dict.size; dict.set(t, id); }
      ids[i] = id;
    }
    return ids;
  };
  const A = encode(ta);
  const B = encode(tb);

  const ops = [];

  // Trim common prefix / suffix.
  let start = 0;
  while (start < N && start < M && A[start] === B[start]) start++;
  let endA = N, endB = M;
  while (endA > start && endB > start && A[endA - 1] === B[endB - 1]) {
    endA--; endB--;
  }

  for (let i = 0; i < start; i++) ops.push([EQ, i]);

  const n = endA - start;
  const m = endB - start;
  if (n > 0 && m > 0) {
    myersOps(A, B, start, endA, start, endB, ops);
  } else {
    for (let i = start; i < endA; i++) ops.push([DEL, i]);
    for (let j = start; j < endB; j++) ops.push([INS, j]);
  }

  for (let i = endA; i < N; i++) ops.push([EQ, i]);

  // Merge adjacent same-op tokens into runs.
  const out = [];
  for (let i = 0; i < ops.length; i++) {
    const [code, idx] = ops[i];
    const op = code === EQ ? 'eq' : code === DEL ? 'del' : 'ins';
    const text = code === INS ? tb[idx] : ta[idx];
    const last = out[out.length - 1];
    if (last !== undefined && last.op === op) last.text += text;
    else out.push({ op, text });
  }
  return out;
}

/**
 * Render a diff op list as inline unified-style markup:
 * deleted words as [-word-], inserted words as {+word+}, equal text as-is.
 */
export function toUnified(ops) {
  let s = '';
  for (const { op, text } of ops) {
    if (op === 'del') s += '[-' + text + '-]';
    else if (op === 'ins') s += '{+' + text + '+}';
    else s += text;
  }
  return s;
}

