import { test } from 'node:test';
import assert from 'node:assert/strict';
import { diff, toUnified } from '../worddiff.mjs';

// ---------- deterministic RNG (mulberry32) so runs are reproducible ----------
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const VOCAB = [
  ...'the quick brown fox jumps over a lazy dog while clouds drift across an open meadow beneath tall silver mountains and quiet rivers run through green valleys where birds sing softly in morning light'.split(' '),
  ...Array.from({ length: 64 }, (_, i) => `w${i}`),
];

const pick = (rng) => VOCAB[Math.floor(rng() * VOCAB.length)];

function differentWord(w, rng) {
  let next = pick(rng);
  while (next === w) next = pick(rng);
  return next;
}

function genDoc(rng, n) {
  return Array.from({ length: n }, () => pick(rng));
}

// Randomly mutate ~rate of positions: replace / delete / insert words.
function mutate(arr, rng, rate) {
  const out = arr.slice();
  const count = Math.max(1, Math.round(out.length * rate));
  for (let c = 0; c < count; c++) {
    const i = Math.floor(rng() * out.length);
    const r = rng();
    if (r < 0.4) {
      out[i] = differentWord(out[i], rng);
    } else if (r < 0.7) {
      out.splice(i, 1);
    } else {
      out.splice(i, 0, pick(rng));
    }
  }
  return out;
}

const concatA = (ops) => ops.filter((o) => o.op !== 'ins').map((o) => o.text).join('');
const concatB = (ops) => ops.filter((o) => o.op !== 'del').map((o) => o.text).join('');

// ------------------------------ correctness ---------------------------------

test('empty vs non-empty', () => {
  assert.deepEqual(diff('', ''), []);
  assert.deepEqual(diff('', 'hello world'), [{ op: 'ins', text: 'hello world' }]);
  assert.deepEqual(diff('hello world', ''), [{ op: 'del', text: 'hello world' }]);
});

test('identical inputs collapse to one eq run', () => {
  assert.deepEqual(diff('the quick brown fox', 'the quick brown fox'), [
    { op: 'eq', text: 'the quick brown fox' },
  ]);
});

test('known small case produces the exact expected op list', () => {
  const ops = diff('the quick brown fox', 'the slow brown fox');
  assert.deepEqual(ops, [
    { op: 'eq', text: 'the ' },
    { op: 'del', text: 'quick' },
    { op: 'ins', text: 'slow' },
    { op: 'eq', text: ' brown fox' },
  ]);
  assert.equal(toUnified(ops), 'the [-quick-]{+slow+} brown fox');
});

test('invariant: eq+del reconstructs a, eq+ins reconstructs b (50 random pairs)', () => {
  const rng = mulberry32(1234);
  for (let i = 0; i < 50; i++) {
    const aArr = genDoc(rng, 10 + Math.floor(rng() * 70));
    const bArr = mutate(aArr, rng, 0.05 + rng() * 0.25);
    const a = aArr.join(' ');
    const b = bArr.join(' ');

    const ops = diff(a, b);

    // valid op values only
    for (const o of ops) {
      assert.ok(o.op === 'eq' || o.op === 'del' || o.op === 'ins', `bad op ${o.op}`);
      assert.equal(typeof o.text, 'string');
    }

    assert.equal(concatA(ops), a, `a reconstruction failed for pair ${i}`);
    assert.equal(concatB(ops), b, `b reconstruction failed for pair ${i}`);

    // no adjacent runs share an op (runs are maximal)
    for (let j = 1; j < ops.length; j++) {
      assert.notEqual(ops[j].op, ops[j - 1].op, `unmerged adjacent runs at pair ${i}`);
    }
  }
});

// ------------------------------- performance --------------------------------

test('perf: 20,000-word docs with 5% differing positions diffs in < 3s', () => {
  const N_WORDS = 20000;
  const rng = mulberry32(42);

  const aArr = genDoc(rng, N_WORDS);
  const bArr = aArr.slice();

  // Replace exactly 5% of positions (distinct indices) with different words.
  const count = Math.floor(N_WORDS * 0.05); // 1000
  const indices = new Set();
  while (indices.size < count) indices.add(Math.floor(rng() * N_WORDS));
  for (const i of indices) bArr[i] = differentWord(bArr[i], rng);

  const a = aArr.join(' ');
  const b = bArr.join(' ');
  assert.notEqual(a, b);

  const t0 = performance.now();
  const ops = diff(a, b);
  const elapsedMs = performance.now() - t0;

  // Sanity: result must still be a correct diff.
  assert.equal(concatA(ops), a);
  assert.equal(concatB(ops), b);

  assert.ok(
    elapsedMs < 3000,
    `diff took ${elapsedMs.toFixed(1)}ms, budget is 3000ms`
  );
});

